-- GENERATED by `wfj generate` from data/gossip/gossip-94.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["94003884c4f97bda"] = { "Addestrami.", "." },
  ["94166c57c2f0306b"] = { "Quale messaggio?", "." },
  ["941a0a7614778640"] = { "%s fugge nel vuoto!", "." },
  ["941d236fc51dcf4b"] = { "Quando ho trovato per caso le pietre Suntara agli Scavi di Golasporca, il potere di Ragnaros mi ha attraversato da capo a piedi. È stato Ragnaros a darmi uno scopo.", "." },
  ["941f28348e525736"] = { "Non è sorprendente ciò che si può creare con le piante della foresta? Davvero, Elune ci ha benedetti con la sua generosità.", "." },
  ["942f612a6d8f07d2"] = { "Esplosioni! ALTRE esplosioni! Mi servono altre esplosioni!", "." },
  ["9439ef9441d45c96"] = { "Non vengono molti cuochi qui a chiedere un addestramento, ma credo di poterti insegnare qualcosa, se te la senti.", "." },
  ["943f8e3213dcf984"] = { "Tu cerca Martha Alliestar. Lei in anello interno di Apothecarium.", "." },
  ["9442f434a53417ed"] = { "Guarda bene dove metti quel piede, <signore/signora>. Non tutti abbiamo la fortuna dell'altezza vertiginosa di <un/una> {race}.", "." },
  ["9449175b62f36c39"] = { "Il ⟦Icewing Bunker=Fortilizio di Algidala⟧ presidia il passo tra il territorio dell'⟦Alliance=Alleanza⟧ e il ⟦Field of Strife=Pian della Discordia⟧.\n\nÈ controllato dall'⟦Alliance=Alleanza⟧.", "." },
  ["944cb17d520882ef"] = { "Ahh, i gemelli Glustewelt!", "." },
  ["944f9d66aca31d47"] = { "Percepisco un turbamento che si aggira intorno a te...", "." },
  ["94522507f9aebc98"] = { "Ho detto IN GINOCCHIO!", "." },
  ["94535c7940879507"] = { "Silenzio! Non posso permettermi di perdere nemmeno un istante di questa lezione!", "." },
  ["945fa1ea89de0a85"] = { "Non devi evocare il nostro dio!", "." },
  ["9464a6a984bc510e"] = { "Studia sodo e un giorno potresti riuscire a evocarne uno per conto tuo, ma per ora è il momento di passare al vilsegugio.", "." },
  ["94682c7cd9887b4f"] = { "Non merito questa conversazione, <padrone/padrona>.", "." },
  ["946fae27ca5aca7c"] = { "Chi controlla il ⟦Icewing Bunker=Fortilizio di Algidala⟧?", "." },
  ["9471734e720da414"] = { "Io... non l'avevo vista in questo modo, Capoguerra.", "." },
  ["948067e0aa6413f1"] = { "Chi mangio per primo? È così difficile scegliere. Hanno tutti un odore delizioso...", "." },
  ["9482b0a4d42e8f26"] = { "%s contrattacca con una rappresaglia.", "." },
  ["9482efc663971eb4"] = { "%s inizia a strofinare la ⟦Tear of the Moons=Lacrima delle Lune⟧.", "." },
  ["948ad9e989886ada"] = { "Tanto tempo fa, prima dell'ultima grande guerra, mio padre gestiva la ⟦Lumber Mill=Segheria⟧ di Cresta Nord. Era la sua vita, e vi si dedicava anima e corpo. Poi arrivò la guerra e, per quanto gli costasse, dovemmo fuggire a ⟦Stormwind=Roccavento⟧.\n\nIn quei giorni perdemmo parecchi amici e familiari, e mi addolora sapere che la ⟦Scarlet Crusade=Crociata Scarlatta⟧ si è presa la segheria per i propri scopi.\n\nEcco perché ho fatto ritorno.", "." },
  ["9490256d7c9e0c6d"] = { "%s guarda {name}, poi piange di gioia.", "." },
  ["94910dcf2ef35f4a"] = { "I nostri antenati ci insegnano che, se il singolo deve essere forte, nel numero c'è sicurezza. Vuoi difendere l'onore di ⟦Thunder Bluff=Picco del Tuono⟧ fondando una gilda?", "." },
  ["94940f7139ec6315"] = { "⟦Brek Stonehoof=Brek Zoccolo Granitico⟧ si trova alla Stonehoof Geology, sul livello inferiore, e può insegnarti il modo giusto di estrarre minerali e gemme preziose.", "." },
  ["949dd18551be2003"] = { "%s inizia a frugare nelle borse in cerca del componente giusto per l'incantesimo.", "." },
  ["94a44003124ddfae"] = { "Radnaal fornisce a Nadyia una buona scorta di cuoio, ricavato dagli animali che scuoia. Ti consiglio di parlare con lui, se vuoi imparare la professione.", "." },
  ["94a71a9488bb1ca6"] = { "Posso insegnarti i segreti di ⟦Raptor Riding=Cavalca-Raptor⟧, purché tu abbia abbastanza oro per pagare la lezione!", "." },
  ["94aa5d1152e59af2"] = { "Le giovani razze? Gli infanti? Umani? Orchi? Nani? Speri di sconfiggere gli Hakkari? Di distruggere un DIO?", "." },
  ["94ae3991bbcaeb40"] = { "Il braciere riflette ancora la luce dei dintorni, e la fiamma ondeggia appena mentre ti avvicini.\n\nLa corruzione sulle colline sembra essersi tenuta a distanza e, a parte i componenti mancanti, il braciere sembra pronto per il rituale che evocherà una manifestazione purificata dell'acqua.", "." },
  ["94b6f5253163279a"] = { "Questo porcile è tutt'altro che comodo, ma ha una storia, quindi ⟦Stonard=Pietrachiusa⟧ deve contare per qualcuno. Scommetto che è per questo che restiamo qui. Di certo non per il panorama: non somiglia neanche a casa.", "." },
  ["94c22f6e36dc7c65"] = { "Tragicamente, fu la saggezza di Thrall a suggellare infine il legame tra il signore dei demoni e i suoi servitori. Fu il reggimento di Trebor a fare da catalizzatore per unire il signore dei demoni, le sette degli Shadowsworn e gli ogre. Il richiamo di un potere quasi illimitato e la promessa di truppe d'assalto immortali a ciascun capo suggellarono il patto col sangue.", "." },
  ["94ca3baf0efabce4"] = { "Vittoria! Per Agamaggan!", "." },
  ["94ca7afefc057b0c"] = { "Troverai Sildinair alla ⟦Warrior's Terrace=Terrazza dei Guerrieri⟧, tra le guardie: i suoi occhi acuti scrutano la foresta in cerca di nemici che osino entrare nella nostra bella città.", "." },
  ["94d095bc9713d85d"] = { "Devi trovare, tra i miserabili nella parte inferiore di questa cittadella, qualcuno che abbia ottenuto un ⟦Unadorned Seal of Ascension=Sigillo dell'Ascesa Disadorno⟧. Per uno degli esseri inferiori è un grande onore ottenere questo oggetto, perché è il primo passo per accedere alla cittadella superiore e diventare una delle guardie scelte di Nefarian, la legione Manonera. Trova un oggetto simile e portamelo, così che possa esaminarne le proprietà. Saprò come procedere una volta completata l'ispezione del sigillo.", "." },
  ["94d6c60c50cf1372"] = { "Capisco, Madre Terra.", "." },
  ["94d7754acf5c16fc"] = { "La buona vecchia Erma si prende cura degli animali del posto da anni ormai. Di sicuro sarà felice di occuparsi di quelli che vuoi lasciarle. La trovi proprio fuori dalla Locanda del Fiero Leone.", "." },
  ["94e3112d2c85f4d6"] = { "Rane e palle di cuoio in vendita!", "." },
  ["94e5c305af97064e"] = { "Mi interessa l'addestramento in alchimia.", "." },
  ["94ea497a80936448"] = { "Grurk aprire presto. Poi noi dividere tesoro.", "." },
  ["94ecbd1964b2872b"] = { "Sì. Certo.", "." },
  ["94f993e0823f4c4f"] = { "Ah, una fiala d'acqua creata e benedetta da Brine, e per giunta raccolta da te.\n\nIl liquido in questa fiala sarà fondamentale per creare un sapta per te, ma servirà anche per un altro compito.\n\nIl sapta che creerò per te dovrà essere usato per vedere gli spiriti dell'acqua al santuario nella ⟦Silverpine Forest=Selva Pinargento⟧, a sud di ⟦Undercity=Sepulcra⟧. Le gocce rimanenti... be', delle gocce rimanenti ti parlerò se ti senti <pronto/pronta>.\n\nSei <preparato/preparata> per un ultimo viaggio, {name}?", "." },
  ["94fd8cfb6c1d3f65"] = { "<Il cadavere davanti a te è coperto di bruciature e segni di fiamme. Sembra stringere qualcosa in mano.>", "." },
})
